class AgentOrchestrator:
    def __init__(self, max_budget_usd: float = 5.0, max_depth: int = 10):
        self.max_budget = max_budget_usd
        self.max_depth = max_depth
        self.spent = 0.0

    # Execute agent decision step with strict cost and cycle detection
    def execute_turn(self, state, tool_call):
        if state.depth >= self.max_depth:
            raise RecursionError("Agent recursion limit reached")
        if self.spent >= self.max_budget:
            raise BudgetExceededError("Agent token budget exceeded")
        return self.sandbox.run_sandboxed(tool_call)
